'use strict';

// A run is authorized once, before acquisition starts. Every point generated by
// the Python worker carries that run ID. This journal closes the gap between
// point creation and Electron's next poll, without enrolling historical data.
const fs = require('node:fs');
const path = require('node:path');
const { randomBytes } = require('node:crypto');
const ID = /^[a-f0-9]{32}$/;
const MAX_JOURNAL_BYTES = 8 * 1024 * 1024;
const ownerOf = binding => binding ? JSON.stringify([binding.serverUrl, binding.user.id, binding.user.tenant]) : '';
const plain = value => value && typeof value === 'object' && !Array.isArray(value);

function createCaptureTracker({ file, dataDir, auth, sync, getSnapshot, intervalMs = 500, now = Date.now }) {
  if (!path.isAbsolute(file || '') || !path.isAbsolute(dataDir || '') || !auth?.cloudBinding || !sync?.observeRecording || typeof getSnapshot !== 'function') throw Error('Invalid capture tracker configuration');
  let saved = { version: 1, runs: [] }, permanentError = '', error = '', work = null, disposed = false, epoch = 0;
  const pending = new Set(), ignored = new Set();
  try {
    const stat = fs.lstatSync(file);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > MAX_JOURNAL_BYTES || (process.platform !== 'win32' && stat.mode & 0o077)) throw Error('invalid capture journal');
    const value = JSON.parse(fs.readFileSync(file, 'utf8'));
    if (!plain(value) || value.version !== 1 || !Array.isArray(value.runs) || value.runs.length > 2000 || value.runs.some(run =>
      !plain(run) || !ID.test(run.id) || typeof run.owner !== 'string' || !run.owner || run.owner.length > 2500 ||
      !Number.isFinite(run.createdAt) || !plain(run.records) || Object.keys(run.records).length > 2000 ||
      Object.entries(run.records).some(([id, state]) => !ID.test(id) || !['complete', 'error'].includes(state))) ||
      new Set(value.runs.map(run => run.id)).size !== value.runs.length) throw Error('invalid capture journal');
    saved = value;
  } catch (cause) {
    if (cause.code !== 'ENOENT') permanentError = '采集同步登记不可用，已保留原文件；本机采集不受影响，请检查登记文件与权限。';
  }
  function persist() {
    if (permanentError) throw Error(permanentError);
    const content = JSON.stringify(saved);
    if (Buffer.byteLength(content) > MAX_JOURNAL_BYTES) throw Error('采集同步登记已满，请完成待同步记录后重试。');
    const temporary = `${file}.${randomBytes(8).toString('hex')}.tmp`;
    let fd;
    try {
      fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
      fd = fs.openSync(temporary, 'wx', 0o600);
      fs.writeFileSync(fd, content); fs.fsyncSync(fd); fs.closeSync(fd); fd = undefined;
      fs.renameSync(temporary, file);
    } finally {
      if (fd !== undefined) fs.closeSync(fd);
      try { fs.unlinkSync(temporary); } catch {}
    }
  }
  function prepare() {
    if (disposed) throw Error('采集同步登记已关闭');
    if (permanentError) throw Error(permanentError);
    const owner = ownerOf(auth.cloudBinding());
    if (!owner || !sync.status().enabled) return null;
    if (saved.runs.length >= 2000) throw Error('采集同步登记已满，请完成待同步记录后重试。');
    const run = { id: randomBytes(16).toString('hex'), owner, createdAt: now(), records: {} };
    saved.runs.push(run); pending.add(run.id); epoch++;
    try { persist(); error = ''; return run.id; }
    catch (cause) { saved.runs = saved.runs.filter(item => item !== run); pending.delete(run.id); error = cause.message; throw cause; }
  }
  function activate(id) {
    if (id) { pending.delete(id); epoch++; }
  }
  async function readManifest(entry, root) {
    const directory = path.join(dataDir, entry.name);
    if (!entry.isDirectory() || entry.isSymbolicLink() || path.dirname(await fs.promises.realpath(directory)) !== root) throw Error('采集记录目录不安全');
    const target = path.join(directory, 'manifest.json');
    const stat = await fs.promises.lstat(target);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 1024 * 1024) throw Error('采集记录元数据不可用');
    const value = JSON.parse(await fs.promises.readFile(target, 'utf8'));
    if (!plain(value) || value.id !== entry.name || !['incomplete', 'complete', 'error'].includes(value.status)) throw Error('采集记录元数据无效');
    return value;
  }
  function scan(snapshotOverride) {
    if (disposed || permanentError || work) return work || Promise.resolve();
    if (!saved.runs.length) return Promise.resolve();
    work = (async () => {
      const stamp = epoch, owner = ownerOf(auth.cloudBinding());
      const runs = saved.runs.filter(run => run.owner === owner && !pending.has(run.id));
      if (!owner || !runs.length) return;
      const snapshot = snapshotOverride || await getSnapshot();
      // A healthy idle service, or a completed shutdown, establishes that no
      // further point manifests can be produced by these runs.
      const inactive = !snapshot?.receiver?.running && !['starting', 'acquiring', 'stopping'].includes(snapshot?.state) &&
        ['ready', 'stopped'].includes(snapshot?.service?.state) && !snapshot?.service?.error;
      const activeId = snapshot?.receiver?.running && snapshot?.recording?.status === 'incomplete' ? snapshot.recording.id : null;
      // Early-pass records can remain in memory until the continuous archive is
      // finalized. Authorize their live preview from this run's current writer;
      // only a terminal on-disk manifest below may enroll a completed upload.
      const current = snapshot?.recording;
      const currentRun = plain(current) && ID.test(current.id) && activeId === current.id &&
        saved.runs.find(run => run.id === current.captureSessionId && run.owner === owner &&
          !pending.has(run.id) && !run.records[current.id]);
      if (currentRun && ownerOf(auth.cloudBinding()) === owner) {
        sync.observeRecording(current, { owner, active: true });
      }
      let entries, root;
      try { root = await fs.promises.realpath(dataDir); entries = await fs.promises.readdir(dataDir, { withFileTypes: true }); }
      catch (cause) { if (cause.code === 'ENOENT') return; throw cause; }
      let completeScan = true;
      for (const entry of entries) {
        if (!ID.test(entry.name) || ignored.has(entry.name)) continue;
        // Use the current journal: a new run may have started during this scan.
        if (saved.runs.some(run => run.records[entry.name])) continue;
        let recording;
        try { recording = await readManifest(entry, root); }
        catch { completeScan = false; error = '部分采集记录未能读取，同步登记稍后重试；原始文件仍保留在本机。'; continue; }
        const run = saved.runs.find(item => item.id === recording.captureSessionId);
        if (!run) { ignored.add(entry.name); continue; }
        if (run.owner !== owner || pending.has(run.id)) continue;
        if (currentRun && recording.id === current.id && recording.status === 'incomplete') continue;
        const active = recording.id === activeId && recording.status === 'incomplete';
        // A newly created next point can appear after the status snapshot.
        // Do not label that point incomplete/error until the worker is idle.
        if (recording.status === 'incomplete' && !active && (!inactive || stamp !== epoch)) continue;
        if (ownerOf(auth.cloudBinding()) !== owner) return;
        const accepted = sync.observeRecording(recording, { owner, active });
        if (!accepted) continue;
        if (recording.status !== 'incomplete' || inactive) {
          run.records[recording.id] = recording.status === 'complete' ? 'complete' : 'error';
          persist();
        }
      }
      if (completeScan && inactive && stamp === epoch && ownerOf(auth.cloudBinding()) === owner) {
        // Queue enrollment is durable before this authorization is retired. A
        // restart therefore never re-enrolls compacted, already synced history.
        const completed = new Set(runs.map(run => run.id));
        saved.runs = saved.runs.filter(run => !completed.has(run.id));
        persist();
      }
      if (completeScan) error = '';
    })().catch(cause => { error = cause.message || '采集同步登记失败，稍后重试；原始记录仍保留在本机。'; }).finally(() => { work = null; });
    return work;
  }
  const timer = setInterval(() => { void scan(); }, intervalMs); timer.unref?.();
  return Object.freeze({
    prepare, activate, scan,
    warning(message) { error = message; },
    status() { return { error: permanentError || error || undefined, pendingRuns: saved.runs.length }; },
    async flush(snapshot) { await work; await scan(snapshot); },
    dispose() { disposed = true; clearInterval(timer); },
    async settled() { await work; },
  });
}
module.exports = { createCaptureTracker };
